     9	
    10	const DAY_MS = 86_400_000;
    11	
    12	function addMonths(date: Date, months: number): Date {
    13	  const result = new Date(date);
    14	  result.setMonth(result.getMonth() + months);
    15	  return result;
    16	}
    17	
    18	function endFromDays(start: Date, days: number | null): Date {
    19	  return new Date(start.getTime() + (days ?? 20) * DAY_MS);
    20	}
    21	
    22	type TimelineRow = {
    23	  id: string;
    24	  kind: "schedule" | "campaign";
    25	  label: string;
    26	  status: string;
    27	  start: Date;
    28	  end: Date;
    29	};
    30	
    31	export function ScheduleTimeline() {
    32	  const router = useRouter();
    33	  const range = useMemo(() => {
    34	    const startsAt = new Date();
    35	    startsAt.setHours(0, 0, 0, 0);
    36	    return { startsAt, endsAt: addMonths(startsAt, 3) };
    37	  }, []);
    38	  const { data, isLoading } = trpc.campaign.getScheduleTimeline.useQuery(range);
    39	
    40	  const rows = useMemo<TimelineRow[]>(() => {
    41	    if (!data) return [];
    42	    const schedules = data.schedules.map((schedule) => {
    43	      const start = new Date(
    44	        Math.max(
    45	          new Date(schedule.startsAt).getTime(),
    46	          range.startsAt.getTime(),
    47	        ),
    48	      );
    49	      const naturalEnd = schedule.endsAt
    50	        ? new Date(schedule.endsAt)
    51	        : schedule.type === "ONE_TIME"
    52	          ? endFromDays(
    53	              new Date(schedule.startsAt),
    54	              schedule.autoCompleteAfterDays,
    55	            )
    56	          : range.endsAt;
    57	      return {
    58	        id: schedule.id,
    59	        kind: "schedule" as const,
    60	        label: schedule.name,
    61	        status: schedule.status,
    62	        start,
    63	        end: new Date(Math.min(naturalEnd.getTime(), range.endsAt.getTime())),
    64	      };
    65	    });
    66	    const campaigns = data.campaigns.map((campaign) => {
    67	      const occurrence = new Date(campaign.occurrenceAt ?? campaign.createdAt);
    68	      return {
    69	        id: campaign.id,
    70	        kind: "campaign" as const,
    71	        label: campaign.name,
    72	        status: campaign.status,
    73	        start: new Date(
    74	          Math.max(occurrence.getTime(), range.startsAt.getTime()),
