    87	  }, [data, range]);
    88	
    89	  const chartData = useMemo<ChartData<"bar", [number, number][], string>>(
    90	    () => ({
    91	      labels: rows.map((row) => row.label),
    92	      datasets: [
    93	        {
    94	          label: "Timeline",
