    96	          backgroundColor: rows.map((row) =>
    97	            row.kind === "schedule"
    98	              ? "rgba(41, 184, 255, 0.78)"
    99	              : "rgba(21, 229, 212, 0.78)",
   100	          ),
   101	          borderColor: rows.map((row) =>
   102	            row.kind === "schedule" ? "#29B8FF" : "#15E5D4",
   103	          ),
   104	          borderWidth: 1,
   105	          borderRadius: 6,
   106	          borderSkipped: false,
   107	          barThickness: 18,
   108	        },
   109	      ],
   110	    }),
   111	    [rows],
   112	  );
   113	
   114	  const options = useMemo<ChartOptions<"bar">>(
   115	    () => ({
   116	      indexAxis: "y",
   117	      maintainAspectRatio: false,
   118	      animation: false,
   119	      onClick: (_event, elements) => {
   120	        const row = rows[elements[0]?.index ?? -1];
   121	        if (row)
   122	          router.push(
   123	            row.kind === "schedule"
   124	              ? `/schedule/${row.id}`
   125	              : `/campaigns/${row.id}`,
   126	          );
