   150	          border: { color: "rgba(255, 255, 255, 0.12)" },
   151	          ticks: {
   152	            color: "#a1a1aa",
   153	            maxTicksLimit: 7,
   154	            callback: (value) =>
   155	              new Intl.DateTimeFormat(undefined, {
   156	                month: "short",
   157	                day: "numeric",
   158	              }).format(new Date(Number(value))),
   159	          },
   160	        },
   161	        y: {
   162	          grid: { display: false },
   163	          border: { display: false },
   164	          ticks: { color: "#d4d4d8" },
   165	        },
   166	      },
   167	    }),
