   187	        </div>
   188	        <div
   189	          className="flex gap-4 text-xs text-zinc-300"
   190	          aria-label="Timeline legend"
   191	        >
   192	          <span className="flex items-center gap-2">
   193	            <span className="h-2.5 w-2.5 rounded-sm bg-brand-blue" />
   194	            Schedules
   195	          </span>
   196	          <span className="flex items-center gap-2">
   197	            <span className="h-2.5 w-2.5 rounded-sm bg-brand-cyan" />
   198	            Campaigns
   199	          </span>
   200	        </div>
   201	      </div>
   202	      {isLoading ? (
   203	        <Skeleton height="18rem" borderRadius="0.75rem" />
   204	      ) : rows.length ? (
   205	        <div style={{ height: `${Math.max(280, rows.length * 42 + 64)}px` }}>
