    11	import { useDataTable } from "@/src/hooks/use-data-table";
    12	import { useLocale } from "@/src/lib/i18n";
    13	import { trpc } from "@/src/lib/trpc";
    14	
    15	export type ScheduleRow = {
    16	  id: string;
    17	  name: string;
    18	  type: "ONE_TIME" | "RECURRING";
    19	  status: "DRAFT" | "SCHEDULED" | "RUNNING" | "COMPLETED" | "CANCELLED";
    20	  startsAt: Date;
    21	  targetTimezone: string;
    22	  frequency: string | null;
    23	  targetGroup: { name: string; _count: { users: number } } | null;
    24	  sources: Array<{ campaign: { name: string } }>;
    25	  _count: { campaigns: number };
    26	};
    27	
    28	function formatLabel(value: string): string {
    29	  return value
    30	    .toLowerCase()
    31	    .replaceAll("_", " ")
    32	    .replace(/^./, (letter) => letter.toUpperCase());
    33	}
    34	
    35	function statusSeverity(status: ScheduleRow["status"]) {
    36	  if (status === "RUNNING") return "success" as const;
    37	  if (status === "SCHEDULED") return "info" as const;
    38	  if (status === "CANCELLED") return "danger" as const;
    39	  if (status === "DRAFT") return "warning" as const;
    40	  return "secondary" as const;
    41	}
    42	
    43	interface ScheduleTableProps {
    44	  onChanged: () => void;
    45	}
    46	
    47	export function ScheduleTable({ onChanged }: ScheduleTableProps) {
    48	  const router = useRouter();
    49	  const locale = useLocale();
    50	  const utils = trpc.useUtils();
    51	  const { setSearch, setSorts, setFilterValues, setPage, buildQueryInput } =
    52	    useDataTable();
    53	  const queryInput = buildQueryInput(["name", "type", "status", "startsAt"]);
    54	  const { data, isLoading } = trpc.campaign.listSchedules.useQuery(queryInput);
    55	  const cancel = trpc.campaign.cancelSchedule.useMutation({
    56	    onSuccess: async () => {
    57	      await utils.campaign.listSchedules.invalidate();
    58	      onChanged();
    59	    },
    60	  });
    61	  const duplicate = trpc.campaign.duplicateSchedule.useMutation({
    62	    onSuccess: async () => {
    63	      await utils.campaign.listSchedules.invalidate();
    64	      onChanged();
    65	    },
    66	  });
    67	  const rows = (data?.rows ?? []) as ScheduleRow[];
    68	
    69	  const columns: DataTableColumn<ScheduleRow>[] = [
    70	    {
    71	      field: "name",
    72	      header: "Name",
    73	      sortable: true,
    74	      body: (schedule) => (
    75	        <button
    76	          type="button"
    77	          className="font-medium text-white hover:text-brand-blue"
    78	          onClick={() => router.push(`/schedule/${schedule.id}`)}
    79	        >
    80	          {schedule.name}
    81	        </button>
    82	      ),
    83	    },
    84	    {
    85	      field: "type",
    86	      header: "Type",
    87	      sortable: true,
    88	      body: (schedule) => (
    89	        <Badge
    90	          value={formatLabel(schedule.type)}
    91	          severity={schedule.type === "RECURRING" ? "info" : "secondary"}
    92	        />
    93	      ),
    94	    },
    95	    {
    96	      field: "status",
    97	      header: "Status",
    98	      sortable: true,
    99	      body: (schedule) => (
   100	        <Badge
   101	          value={formatLabel(schedule.status)}
   102	          severity={statusSeverity(schedule.status)}
   103	        />
   104	      ),
   105	    },
   106	    {
   107	      field: "frequency",
   108	      header: "Cadence",
   109	      body: (schedule) =>
   110	        schedule.frequency ? formatLabel(schedule.frequency) : "One time",
   111	    },
   112	    {
   113	      field: "sources",
   114	      header: "Campaign source",
   115	      body: (schedule) => (
   116	        <div className="max-w-64 text-sm">
   117	          <p className="truncate text-zinc-200">
   118	            {schedule.sources.map(({ campaign }) => campaign.name).join(", ")}
   119	          </p>
   120	          <p className="text-xs text-zinc-500">
   121	            {schedule._count.campaigns} generated campaign
   122	            {schedule._count.campaigns === 1 ? "" : "s"}
   123	          </p>
   124	        </div>
   125	      ),
   126	    },
   127	    {
   128	      field: "targetGroup",
   129	      header: "Audience",
   130	      body: (schedule) =>
   131	        schedule.targetGroup ? (
   132	          <div className="text-sm">
   133	            <p className="text-zinc-200">{schedule.targetGroup.name}</p>
   134	            <p className="text-xs text-zinc-500">
   135	              {schedule.targetGroup._count.users} recipients
   136	            </p>
   137	          </div>
   138	        ) : (
   139	          <span className="text-zinc-500">Inherited</span>
   140	        ),
   141	    },
   142	    {
   143	      field: "startsAt",
   144	      header: "Starts",
   145	      sortable: true,
   146	      body: (schedule) =>
   147	        new Date(schedule.startsAt).toLocaleString(locale, {
   148	          dateStyle: "medium",
   149	          timeStyle: "short",
   150	          timeZone: schedule.targetTimezone,
   151	        }),
   152	    },
   153	  ];
   154	
   155	  const filters: DataTableFilter[] = [
   156	    {
   157	      field: "type",
   158	      label: "Type",
   159	      type: "select",
   160	      options: ["ONE_TIME", "RECURRING"].map((value) => ({
   161	        label: formatLabel(value),
   162	        value,
   163	      })),
   164	    },
   165	    {
   166	      field: "status",
   167	      label: "Status",
   168	      type: "select",
   169	      options: ["DRAFT", "SCHEDULED", "RUNNING", "COMPLETED", "CANCELLED"].map(
   170	        (value) => ({ label: formatLabel(value), value }),
   171	      ),
   172	    },
   173	  ];
   174	
   175	  const actions: DataTableAction<ScheduleRow>[] = [
   176	    {
   177	      label: "View details",
   178	      icon: "pi pi-eye",
   179	      onClick: (schedule) => router.push(`/schedule/${schedule.id}`),
   180	    },
   181	    {
   182	      label: "Duplicate",
   183	      icon: "pi pi-copy",
   184	      onClick: (schedule) => duplicate.mutate({ id: schedule.id }),
   185	    },
   186	    {
   187	      label: "Cancel schedule",
   188	      icon: "pi pi-times",
   189	      severity: "danger",
   190	      visible: (schedule) =>
   191	        !["COMPLETED", "CANCELLED"].includes(schedule.status),
   192	      onClick: (schedule) => cancel.mutate({ id: schedule.id }),
   193	    },
   194	  ];
   195	
   196	  return (
   197	    <section aria-labelledby="schedule-table-heading">
   198	      <div className="mb-4">
   199	        <h2
   200	          id="schedule-table-heading"
   201	          className="text-lg font-semibold text-white"
   202	        >
   203	          Schedule database
   204	        </h2>
   205	        <p className="mt-1 text-sm text-zinc-400">
   206	          Search, filter, and manage all campaign schedules.
   207	        </p>
   208	      </div>
   209	      <AppDataTable
   210	        data={rows}
   211	        total={data?.total ?? 0}
   212	        columns={columns}
   213	        dataKey="id"
   214	        loading={isLoading}
   215	        searchPlaceholder="Search schedules"
   216	        filters={filters}
   217	        actions={actions}
   218	        onSearch={setSearch}
   219	        onSort={setSorts}
   220	        onFilter={setFilterValues}
   221	        onPage={(offset, limit) => setPage({ offset: offset * limit, limit })}
   222	      />
   223	    </section>
   224	  );
   225	}
