     1	"use client";
     2	
     3	import { DataTable as PrimeDataTable } from "primereact/datatable";
     4	import { Column } from "primereact/column";
     5	import { InputText } from "primereact/inputtext";
     6	import type { AppDataTableProps } from "./types";
     7	import { FilterBar } from "./filter-bar";
     8	import { ActionColumn } from "./action-column";
     9	import { useTableState } from "@/src/hooks/use-table-state";
    10	import { useTranslation } from "@/src/lib/i18n";
    11	
    12	const ROWS_PER_PAGE_OPTIONS = [10, 25, 50, 100];
    13	
    14	// eslint-disable-next-line @typescript-eslint/no-explicit-any
    15	export function AppDataTable<T extends Record<string, any>>({
    16	  data,
    17	  total,
    18	  columns,
    19	  dataKey,
    20	  loading = false,
    21	  searchPlaceholder = "Search...",
    22	  filters,
    23	  actions,
    24	  onSearch,
    25	  onSort,
    26	  onFilter,
    27	  onPage,
    28	  defaultRows = 10,
    29	  rowsPerPageOptions = ROWS_PER_PAGE_OPTIONS,
    30	}: AppDataTableProps<T>) {
    31	  const t = useTranslation();
    32	  const { state, setSearch, setSorts, setPage, setFilter, multiSortMeta } =
    33	    useTableState({ defaultRows, onSearch, onSort, onFilter, onPage });
    34	
    35	  const header = (
    36	    <div className="flex items-center gap-4">
    37	      <div className="relative flex-1 max-w-sm">
    38	        <i className="pi pi-search absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400 text-sm" />
    39	        <InputText
    40	          value={state.search}
    41	          onChange={(e) => setSearch(e.target.value)}
    42	          placeholder={searchPlaceholder}
    43	          pt={{
    44	            root: {
    45	              className: "w-full text-xs py-2 pl-9 pr-3",
    46	            },
    47	          }}
    48	        />
    49	      </div>
    50	      {filters && filters.length > 0 && (
    51	        <FilterBar
    52	          filters={filters}
    53	          values={state.filterValues}
    54	          onChange={setFilter}
    55	        />
    56	      )}
    57	    </div>
    58	  );
    59	
    60	  return (
    61	    <PrimeDataTable
    62	      value={data}
    63	      lazy
    64	      paginator
    65	      first={state.first}
    66	      rows={state.rows}
    67	      totalRecords={total}
    68	      rowsPerPageOptions={rowsPerPageOptions}
    69	      paginatorTemplate="RowsPerPageDropdown FirstPageLink PrevPageLink CurrentPageReport NextPageLink LastPageLink"
    70	      currentPageReportTemplate={t("common.currentPageReport")}
    71	      onPage={setPage}
    72	      sortMode="multiple"
    73	      multiSortMeta={multiSortMeta}
    74	      onSort={setSorts}
    75	      removableSort
    76	      loading={loading}
    77	      showGridlines
    78	      header={header}
    79	      emptyMessage={t("common.noRecordsFound")}
    80	      size="normal"
    81	      dataKey={dataKey as string}
    82	      tableStyle={{ minWidth: "50rem" }}
    83	    >
    84	      {columns.map((col) => (
    85	        <Column
    86	          key={col.field}
    87	          field={col.field}
    88	          header={col.header}
    89	          sortable={col.sortable}
    90	          body={col.body}
    91	          style={col.style}
    92	        />
    93	      ))}
    94	      {actions && actions.length > 0 && (
